CSS:
body{font-family:{{font_body}};margin:0;padding:0;background:{{bg}};color:{{text}};line-height:{{line_height}}}
header{background:{{header_bg}};color:{{header_fg}};padding:32px 20px;text-align:center}
header h1{font-size:{{heading_size}}rem;margin:0 0 8px 0;font-weight:700}
header p{font-size:1rem;margin:0}
header p span{opacity:{{tagline_opacity}}}
nav{background:{{nav_bg}};padding:12px 20px;text-align:center}
nav a{color:{{nav_fg}};text-decoration:none;margin:0 18px;font-size:.95rem;font-weight:500;transition:color .2s}
nav a:hover{color:{{nav_fg_hover}}}
main{max-width:{{max_width}}px;margin:40px auto;padding:32px;background:{{surface}};border-radius:{{radius}}px;box-shadow:0 2px 8px {{shadow}}}
main h2{font-size:1.5rem;margin-top:0;color:{{heading_color}}}
main a{color:{{accent_text}}}
main p{margin:16px 0;font-size:1rem}
footer{text-align:center;padding:24px;color:{{text_muted}};font-size:.85rem;border-top:1px solid {{border}}}
footer a{color:{{accent_text}}}

